<!-- 修改昵称页面 -->
<template>
	<view class="page">
		<view class="single-line-box" style="">
			
			<input 
				class="nickname-input"
				type="text" 
				:value="nickname" 
				:model="nickname" 
				placeholder="请填入邮箱地址~"/>
			
			<view class="" style="width: 95%; margin-top: 10px;">
				<text class="tips">*注：填写正确的邮箱有助于候选人联系你噢~</text> 
			</view>
		</view>
		
	</view>
</template>

<script>
	var app = getApp();
	export default {
		data() {
			return {
				// oldNickname: getApp().getUserInfoSession().nickname,
				// nickname: getApp().getUserInfoSession().nickname,
				nickname: "",
				wordsLength: 0
			}
		},
		onNavigationBarButtonTap() {
			var nickname = this.nickname;
			if (nickname.length > 12 || nickname.length < 2) {
				uni.showToast({
					icon: "none",
					title: "昵称长度为2-12"
				})
				return;
			}
			
			var oldNickname = this.oldNickname;
			if (oldNickname == nickname) {
				uni.showToast({
					icon: "none",
					title: "昵称相同"
				})
				return;
			}
			
			this.updateNickname();
		},
		onShow() {
			this.wordsLength = this.nickname.length;
		},
		methods: {
			updateNickname() {
				var me = this;
				var userId = getApp().getUserInfoSession().id;
				var nickname = this.nickname;
				
				var pendingUserInfo = {
					"id": userId,
					"nickname": nickname
				};
				
				// 修改昵称
				var serverUrl = app.globalData.serverUrl;
				uni.request({
					method: "POST",
					header: {
						headerUserId: userId,
						headerUserToken: app.getUserSessionToken()
					},
					url: serverUrl + "/userInfo/modifyUserInfo?type=1",
					data: pendingUserInfo,
					success(result) {
						
						if (result.data.status == 200) {
							var userInfoUpdated = result.data.data;
							// 重置本地用户信息
							app.setUserInfoSession(userInfoUpdated);
							
							uni.navigateBack({
								delta: 1,
								animationType: "fade-out"
							})
						} else {
							uni.showToast({
								title: result.data.msg,
								icon: "none",
								duration: 3000
							});
						}
						
					}
				})
			},
			
		}
	}
</script>

